head.script:
scwin.gVar = {
    "cRef" : "",
    "cRefSync" : "",
    "bInit" : false,
}



// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[secret > P > ref]<br/>Secret 컴포넌트의 입력값에 바인딩할 DataCollection 정보를 설정합니다.",
    "validation" : [
        "바인딩 된 DataCollection 에 입력값이 반영되는 시점은 refSync 속성값에 따라 달라집니다.",
        "DataList 의 선택이 변경되면 Secret 컴포넌트의 입력값이 변경되고 onchange 이벤트가 발생합니다.",
        "사용자에 의해 Secret 컴포넌트의 입력값이 변경되면 onchange, onviewchange 이벤트가 모두 발생합니다.",
    ]
}



scwin.onpageload = function () {
    // Global DataList 생성 호출 (gdm_ref, gdl_ref, gdl_boolean)
    $c.gcm.createCommonDatalist();

    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);

    // 정적 select1 기본값 설정 (gdl_boolean 은 코드값 1=미설정 / 2=true / 3=false)
    con_ref.setSelectedIndex(0);
    con_refSync.setValue("1");

    // comp 초기 생성
    scwin.comp_init();
};



// comp 생성
scwin.comp_init = async function () {
    // 초기 생성 중 스크립트에 의한 값 변경이 이벤트 출력으로 나가지 않도록 차단
    scwin.gVar["bInit"] = true;

    // 기존 컴포넌트 있으면 삭제
    if (typeof label1 !== 'undefined') {
        label1.remove();
    }

    if (typeof target1 !== 'undefined') {
        target1.remove();
    }

    if (typeof label2 !== 'undefined') {
        label2.remove();
    }

    if (typeof mirror1 !== 'undefined') {
        mirror1.remove();
    }

    $c.gcm.createLabel('label="[전제] target1 은 Secret 컴포넌트이며 con_ref, con_refSync 에서 선택한 값이 속성으로 적용됩니다\nTarget 재생성 시 gdm_ref.key1 은 dm_data 로 초기화되고 gdl_ref 는 미선택 상태가 됩니다\n아래 바인딩 데이터 값 은 target1 과 같은 DataCollection 에 바인딩된 표시 전용 textbox 라 포커스를 옮기지 않고도 반영 시점을 볼 수 있습니다\n[절차] 위 조건 선택 -> Target 재생성 -> 검증 목적에 따라 아래 중 하나를 수행\n - refSync 반영 시점 : target1 에 타이핑하면서 바인딩 데이터 값 표시가 즉시 바뀌는지 관찰 -> Enter 또는 Tab 또는 다른 곳 클릭 -> 값 확인 클릭\n - DataList 선택 변경 : ref 를 data:gdl_ref.label 로 재생성 -> DataList 행0 선택 -> DataList 행1 선택\n - 사용자 입력 변경 : target1 에 직접 타이핑 -> 다른 곳 클릭하여 포커스 해제\n[확인] password 라 화면으로 값을 읽을 수 없으므로 바인딩 데이터 값 표시와 결과창의 이벤트 발생 줄로 판정"', '', 'label1');

    // 조건 설정
    scwin.gVar["cRef"] = con_ref.getText();
    scwin.gVar["cRefSync"] = con_refSync.getText();

    // 바인딩 데이터 초기화 (dataMap 은 초기값, DataList 는 미선택 상태)
    gdm_ref.set("key1", "dm_data");
    gdl_ref.setRowPosition(-1);

    let properties = {
        ref : scwin.gVar["cRef"],
        refSync : scwin.gVar["cRefSync"],
    }

    let cList = $c.gcm.createCList(properties);
    let eList = $c.gcm.createEList(["onchange", "onviewchange"]);

    // comp 생성 함수 호출 (헬퍼가 생성 직후 setValue 로 초기값 secret 설정)
    await $c.gcm.createBasicSecret(cList, eList);

    // 헬퍼가 넣은 초기값을 지워 ref 바인딩 결과만 입력창에 남긴다
    target1.setValue("");

    if (scwin.gVar["cRef"] === "data:gdm_ref.key1")
        gdm_ref.set("key1", "dm_data");

    // 바인딩 데이터 값을 실시간으로 표시할 textbox (target1 과 동일 DataCollection 바인딩)
    $c.gcm.createLabel('label="바인딩 데이터 값 : "', '', 'label2');

    let strMirror = '<w2:textbox ' + $c.gcm.strNameSpace + ' id="mirror1" ref="' + scwin.gVar["cRef"] + '" class="tc_tbx_label_1" style="margin:5px;"></w2:textbox>';
    scwin.mirror1 = await $p.dynamicCreate("mirror1", "textbox", strMirror, $c.gcm.getTestGroup(''));

    // DataList 바인딩일 때만 선택 조작 버튼 사용
    let bList = (scwin.gVar["cRef"] === "data:gdl_ref.label");
    btn_selectRow0.setDisabled(!bList);
    btn_selectRow1.setDisabled(!bList);

    scwin.gVar["bInit"] = false;
}



// 미설정 표기 변환
scwin.fn_disp = function (strValue) {
    return (strValue === "") ? "미설정" : strValue;
}



// 바인딩 된 DataCollection 에 저장된 값
scwin.fn_bound = function () {
    if (scwin.gVar["cRef"] === "data:gdm_ref.key1")
        return gdm_ref.get("key1");

    let nRow = gdl_ref.getRowPosition();
    return (nRow < 0) ? "선택된 행 없음" : gdl_ref.getCellData(nRow, "label");
}



// 포커스 해제 후 DataCollection 반영 결과 확인 - validation 1 판정 출력
scwin.btn_getValue_onclick = function (e) {
    wf_body_bottom.getObj("scwin").setReturnValue("ref " + scwin.gVar["cRef"] + " / refSync " + scwin.fn_disp(scwin.gVar["cRefSync"]) + " -> target1 값 : " + (target1.getValue() || "") + " / 바인딩 데이터 값 : " + scwin.fn_bound());
}



// DataList 선택 변경 (validation 2 발동 수단)
scwin.btn_selectRow0_onclick = function (e) {
    gdl_ref.setRowPosition(0);
}



scwin.btn_selectRow1_onclick = function (e) {
    gdl_ref.setRowPosition(1);
}



// validation 2, 3 판정 출력 (핸들러별 즉시 1줄 출력)
scwin.target1_onchange = function (e) {
    if (scwin.gVar["bInit"])
        return;

    wf_body_bottom.getObj("scwin").setReturnValue("onchange 발생 -> target1 값 : " + (target1.getValue() || "") + " / 바인딩 데이터 값 : " + scwin.fn_bound());
}



// validation 3 판정 출력 (핸들러별 즉시 1줄 출력)
scwin.target1_onviewchange = function (info) {
    if (scwin.gVar["bInit"])
        return;

    wf_body_bottom.getObj("scwin").setReturnValue("onviewchange 발생 -> info.oldValue : " + info.oldValue + " / info.newValue : " + info.newValue);
}
